def sort_by_age(people, max_age):
    count = [0] * (max_age + 1)
    for _, age in people:
        count[age] += 1
    start, total = [0] * (max_age + 1), 0
    for age in range(max_age + 1):
        start[age] = total
        total += count[age]
    out = [None] * len(people)
    for person in people:
        out[start[person[1]]] = person
        start[person[1]] += 1
    return out

