record Person(String name, int age) {}

static Person[] sortByAge(Person[] people, int maxAge) {
    int[] count = new int[maxAge + 1];
    for (Person p : people) count[p.age()]++;
    int[] start = new int[maxAge + 1];
    for (int age = 0, total = 0; age <= maxAge; age++) {
        start[age] = total;
        total += count[age];
    }
    Person[] out = new Person[people.length];
    for (Person p : people)
        out[start[p.age()]++] = p;
    return out;
}

