typedef struct {
    const char* name;
    int age;
} Person;

void sortByAge(const Person* people, int n, int maxAge, Person* out) {
    int* count = calloc(maxAge + 1, sizeof(int));
    for (int i = 0; i < n; i++) count[people[i].age]++;
    int* start = calloc(maxAge + 1, sizeof(int));
    for (int age = 0, total = 0; age <= maxAge; age++) {
        start[age] = total;
        total += count[age];
    }
    for (int i = 0; i < n; i++)
        out[start[people[i].age]++] = people[i];
    free(count);
    free(start);
}

