static int[] radixSort(int[] nums) {
    int[] out = nums.clone();
    int biggest = 0;
    for (int x : out) biggest = Math.max(biggest, x);
    for (long place = 1; biggest / place > 0; place *= 10) {
        int[] count = new int[10];
        for (int x : out) count[(int) (x / place % 10)]++;
        for (int d = 1; d < 10; d++) count[d] += count[d - 1];
        int[] next = new int[out.length];
        for (int i = out.length - 1; i >= 0; i--)
            next[--count[(int) (out[i] / place % 10)]] = out[i];
        out = next;
    }
    return out;
}

