void radixSort(int* a, int n) {
    int biggest = 0;
    for (int i = 0; i < n; i++) if (a[i] > biggest) biggest = a[i];
    int* next = malloc((n > 0 ? n : 1) * sizeof(int));
    for (long long place = 1; biggest / place > 0; place *= 10) {
        int count[10] = {0};
        for (int i = 0; i < n; i++) count[a[i] / place % 10]++;
        for (int d = 1; d < 10; d++) count[d] += count[d - 1];
        for (int i = n - 1; i >= 0; i--)
            next[--count[a[i] / place % 10]] = a[i];
        memcpy(a, next, n * sizeof(int));
    }
    free(next);
}
